<script setup>
import { ref, onMounted, inject } from 'vue';
const router = inject('router');
// import { useRouter } from 'vue-router';
// import { ModelList } from '../configs'
// import SuccessDialog from '../components/successDialog.vue'
// const router = useRouter();
const modelList = ref([]);
const modelUrl = ref('');
const show = ref(false);
const useSceneViewer = ref(true); // false: 元宇宙查看器, true: 场景查看器
// const contentRef = ref(null);

onMounted(async () => {
  //   const el = contentRef.value;
  //   console.log(1, el);
  //   el.addEventListener('touchstart', handleTouchStart, { passive: false });
  //   el.addEventListener('touchmove', handleTouchMove, { passive: false });
  try {
    // 使用代理路径，避免 CORS 跨域问题
    const requestFile = await fetch(
      'https://mogs-1300354879.cos.ap-shanghai.myqcloud.com/mogs/nobody/gs-viewer/config/scene_v2.json'
    );
    
    if (requestFile.status !== 200) {
      throw new Error(`加载失败: ${requestFile.statusText}`);
    }
    
    const content = await requestFile.json();
    modelList.value = content;
    console.log('成功加载场景配置:', content);
  } catch (error) {
    console.error('加载场景配置失败:', error);
  }
  // document.addEventListener('touchmove', touchHandler, { passive: false });
});

const goToModel = (itemInfo) => {
  console.log('goToModel===', itemInfo);
  // 根据开关选择不同的查看器
  const viewerPath = useSceneViewer.value ? '/viewer2' : '/viewer';
  // 根据查看器类型选择不同的URL字段
  const sceneUrl = useSceneViewer.value ? itemInfo.modelUrlV2 : itemInfo.modelUrl;
  let url = `${viewerPath}?sceneUrl=${sceneUrl}`;
  console.log('使用的URL:', sceneUrl, '查看器类型:', useSceneViewer.value ? '场景查看器' : '元宇宙查看器');
  // const index = location.href.indexOf('home.html');
  // console.log('index===', index, location.href.slice(0, index));
  // const fullUrl = `${location.href.slice(0, index)}index.html#${url}`;
  // console.log('baseUrl===', fullUrl);
  // window.location.href = fullUrl;
  // window.location.hash = `#${viewerPath}?sceneUrl=${sceneUrl}`;
  router.push({
    path: viewerPath,
    query: {
      sceneUrl
    }
  });
};
const goToViewer = () => {
  console.log('goToViewer===');
  if (modelUrl.value) {
    // const index = location.href.indexOf('home.html');
    console.log('goToModel===', location.href);
    // 根据开关选择不同的查看器
    const viewerPath = useSceneViewer.value ? '/viewer2' : '/viewer';
    // const fullUrl = `${location.href.slice(0, index)}index.html#${viewerPath}?sceneUrl=${modelUrl.value}`;
    // window.location.href = fullUrl;
    // window.location.hash = `#${viewerPath}?sceneUrl=${modelUrl.value}`;
    router.push({
      path: viewerPath,
      query: {
        sceneUrl: modelUrl.value
      }
    });
  }
};
// 定义事件处理函数（避免匿名函数，方便后续解绑）
// const touchHandler = (e) => {
//   // 仅阻止页面顶部下拉的伸缩行为
//   if (document.documentElement.scrollTop < 0) {
//     e.preventDefault();
//   }
// };
const handleTouchStart = (e) => {
  const el = contentRef.value;
  console.log('handleTouchStart===', el);
  const scrollTop = el.scrollTop;
  const scrollHeight = el.scrollHeight;
  const offsetHeight = el.offsetHeight;

  // 判断是否滚动到最顶部或底部
  el._isAtTop = scrollTop === 0;
  el._isAtBottom = scrollTop + offsetHeight >= scrollHeight;
  el._startY = e.touches[0].clientY;
};

const handleTouchMove = (e) => {
  const el = contentRef.value;
  console.log('handleTouchMove===', el);
  const currentY = e.touches[0].clientY;
  const diffY = currentY - el._startY;

  // 到顶部且继续往下拉，或到底部继续往上拉，阻止默认回弹
  if ((el._isAtTop && diffY > 0) || (el._isAtBottom && diffY < 0)) {
    // e.preventDefault(); // 阻止回弹
  }
};
